import{_ as a}from"./chunks/forest.DT9MO_gK.js";import{_ as s,o as t,c as r,a5 as o}from"./chunks/framework.DrDMl0tG.js";const g=JSON.parse('{"title":"Rayrai Example: Forest","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_forest.md","filePath":"sections/examples/rayrai/rayrai_forest.md"}'),i={name:"sections/examples/rayrai/rayrai_forest.md"};function d(n,e,c,h,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="rayrai-example-forest" tabindex="-1">Rayrai Example: Forest <a class="header-anchor" href="#rayrai-example-forest" aria-label="Permalink to &quot;Rayrai Example: Forest&quot;">​</a></h1><p><img src="'+a+`" alt="rayrai_forest example"></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Renders an 80 m × 80 m rolling heightmap covered by instanced Poly Haven vegetation: 1,888 trees, 61,200 ground-cover instances, and 180 mossy rocks. One hundred dynamic props (crates, balls, capsules, and spheres dropped onto tree crowns) fall onto the same heightmap that places the plants. Ground cover is visual-only. Trees and rocks collide through static collision proxies loaded from each asset&#39;s <code>model.rasset</code>.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_forest</code> (C++20).</p><p>The example needs rayrai 2.7.0 or newer. On Linux, the 2.7.0 package can throw <code>std::bad_alloc</code> from <code>InstancedVisuals::addInstances</code> with newer libstdc++ versions; v2.8.0 fixes it (see <a href="./../../changelog/v2.8.html">Changelog: v2.8</a>).</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_forest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_forest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --assets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/forest</span></span></code></pre></div><p>On Windows, run <code>rayrai_forest.exe</code> instead. The asset directory defaults to <code>rsc/forest</code> in the checkout used to configure the build. Copy that directory and pass <code>--assets</code> when you move the executable. The example renders in process and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="loading-the-forest-from-a-scene-file" tabindex="-1">Loading the forest from a scene file <a class="header-anchor" href="#loading-the-forest-from-a-scene-file" aria-label="Permalink to &quot;Loading the forest from a scene file&quot;">​</a></h2><p>The same world is saved as <code>rsc/forest/rayrai_forest.rscene</code>. <a href="./rayrai_forest_from_rscene.html">Rayrai Example: Forest From .rscene</a> builds it from that file with <code>raisim::World(path)</code>, shown by a <code>RayraiWindow</code>, instead of placing it in C++, and simulates identically. The reader is new in v2.8.0, and the <code>RayraiWindow</code> display needs v2.8.2 (not yet released); <a href="./../../RsceneFile.html">.rscene File</a> describes the file format.</p><h2 id="loading-and-caches" tabindex="-1">Loading and caches <a class="header-anchor" href="#loading-and-caches" aria-label="Permalink to &quot;Loading and caches&quot;">​</a></h2><p>Meshes load asynchronously while a progress bar across the top of the window counts the finished assets; physics starts once loading completes. The first launch builds mesh LODs for the high-detail plants and takes several seconds longer (about 10 s in total on a 20-thread desktop). Rayrai saves the prepared levels beside each model as <code>rayrai_cache_model.gltf.lods</code>, and the prepared geometry and import description of the three trees as <code>.rgeo</code> and <code>.rimp</code> files, and reads them on later launches, which then import no tree at all. When the asset directory is read-only, the cache goes to the system temporary directory instead. Set <code>RAYRAI_ASYNC_LOD_CACHE_DIR</code> to choose a cache directory. The cache files are ignored by Git and can be deleted at any time.</p><p>Instance transform records are also cached for single-part foliage batches with up to 32,768 instances, including the 18,000-instance grass batches. The cache reuses the original computed values across scene and shadow selections and is invalidated by instance or distance-fade edits. Each 18,000-instance batch uses about 1.37 MiB for these records, plus validity flags. Geometry, draw order, shader arithmetic and quality settings stay the same. This reduces CPU preparation work.</p><p>When collecting cached records into draw batches, the renderer copies complete records directly into the retained batch bytes. Compile-time size and member offset checks ensure identical source and destination layouts. This removes an intermediate record without changing floating-point arithmetic or cache storage; invalidated records still follow the original computation path.</p><p>For individually selected foliage LODs, the renderer also reuses the exact color-LOD choice across passes with identical camera and LOD inputs. Each shadow cascade retains its own visibility tests and shadow LOD choice. Camera, instance, bounds, wind and LOD-policy changes invalidate this cache. It stores one byte per rendered instance and mesh part and keeps the original arithmetic and thresholds.</p><p>On 64-bit hosts, ground-cover groups with 8,192–32,768 visible instances sort packed depth keys and instance IDs in the existing scratch vectors. This avoids repeated depth loads and conversion while preserving the exact final depth/ID ordering, including tied depths and signed zero. Other sizes and 32-bit hosts keep the existing ID-based radix sort. For packed groups, unsorted IDs, IDs above the 32-bit range and NaNs use the comparison-sort path. The CPU sorting test covers both size boundaries and arbitrary float patterns; the GPU preparation test also checks fully visible groups for exact draw order, color and depth. This reduces sorting work.</p><p>Visibility diagnostics for meshes with several parts count each instance once across overlapping LOD groups. Batches with up to 1,024 candidate instances (after the render-count limit, before culling and stride) use byte flags, including the forest&#39;s tree batches; larger batches retain packed flags. This adds at most 1 KiB of byte flags per eligible batch and preserves exact counts and draw records. The preparation test covers both sides of the boundary, shrink/regrow, render limits, strides and cached selections. This reduces CPU bookkeeping.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Uses one 161 × 161 heightmap for both collision and plant placement, with a fixed-seed scatter.</li><li>Adds the tree and rock collision proxies with <code>raisim::Rasset::load</code> and <code>Rasset::addStaticColliders</code>.</li><li>Renders ten plant types and six rock shapes as <code>InstancedVisuals</code> with automatic mesh LOD, projected-size thinning, foliage shadow LOD, per-type wind, and shadows enabled for every batch.</li><li>Uses the <code>High</code> preset with ACES tone mapping, 4× MSAA, three directional shadow cascades out to 80 m, and clear weather with a distance haze.</li><li>Integrates eight 2 ms physics steps per rendered frame.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>The forest checks live in the RaiSim source repository (<code>test/examples</code>) and are registered when that repository is configured with <code>-DRAISIM_TEST=ON</code> next to this checkout. They cover terrain placement and physics, the <code>.rscene</code> reader, and asset integrity (needs Python 3); with <code>-DRAISIM_RAYRAI_TEST=ON</code> they also cover the loading overlay. <code>-DRAISIM_FOREST_GPU_TESTS=ON</code> adds rendering smoke tests and foliage-shadow checks, which need a display and OpenGL. <code>FOREST.md</code> lists the build and <code>ctest</code> commands. The scatter regression compares transform fields bit-for-bit with the original placement algorithm. The Rayrai <code>rayrai_foliage_preparation_test</code> also compares cached and uncached GPU instance records, color bytes and depth bytes exactly at the forest batch size and cache boundaries, including edits and cache re-enabling. Detailed foliage checks include exact index geometry across color and shadow passes with changing cameras and LOD policies. The CPU <code>rayrai_foliage_color_lod_cache_test</code> covers reuse, all invalidating inputs and floating-point boundaries. The separate <code>rayrai_foliage_color_lod_cache_gpu_test</code> runs the color-cache byte comparisons via <code>rayrai_foliage_preparation_test --color-lod-cache</code>.</p><p>The assets are from Poly Haven under CC0; see <code>rsc/forest/ATTRIBUTION.md</code>. <code>examples/src/rayrai/worlds/FOREST.md</code> documents asset preparation, the build and test commands, and the LOD cache.</p>`,25)])])}const f=s(i,[["render",d]]);export{g as __pageData,f as default};
